For ClientB (using t instead of s):

```json
{
  "ClientA.dfy": "include "Facts.dfy"
module ClientA {
  import F = Facts`ViewA
  lemma Prove(s: nat, t: nat, u: nat, k: nat)
    requires F.Value(s) > k
    ensures F.Large(F.Pair(F.Pair(F.Step(s), F.Step(t)), F.Step(u)), k + 3)
  {
    F.LiftA(s);
    F.LiftA(t);
    F.LiftA(u);
    F.JoinA(F.Step(s), F.Step(t));
    F.JoinA(F.Pair(F.Step(s), F.Step(t)), F.Step(u));
    F.Finish(F.Pair(F.Pair(F.Step(s), F.Step(t)), F.Step(u)), k + 3);
  }
}
",
  "ClientB.dfy": "include "Facts.dfy"
module ClientB {
  import F = Facts`ViewA
  lemma Prove(s: nat, t: nat, u: nat, k: nat)
    requires F.Value(t) > k
    ensures F.Large(F.Pair(F.Pair(F.Step(t), F.Step(u)), F.Step(s)), k + 3)
  {
    F.LiftA(t);
    F.LiftA(u);
    F.LiftA(s);
    F.JoinA(F.Step(t), F.Step(u));
    F.JoinA(F.Pair(F.Step(t), F.Step(u)), F.Step(s));
    F.Finish(F.Pair(F.Pair(F.Step(t), F.Step(u)), F.Step(s)), k + 3);
  }
}
"
}
```

